        (role, sport_scope, term_id, nominated_user_id, nominated_by_user_id, created_at)
        VALUES (?, ?, ?, ?, ?, ?)""", (body.role, body.sport_scope, body.term_id, body.nominee_user_id, user["id"], _now()))
    conn.commit()
