  syncTeamOptions();

  const scope = state.session?.role === "REP" ? state.session.sportScope : null;
  const rosterTeam = maybe<HTMLSelectElement>("p-team");
  if (rosterTeam) {
    const keep = rosterTeam.value;
    clear(rosterTeam);
