  pop(button);
  clear(out);
  ($("login-password") as HTMLInputElement).value = "";
  renderSession();
  fillSelects();
  loadPending();
  toast("Signed in",
    `${res.body.role}${res.body.sport_scope ? " Â· " + res.body.sport_scope : " Â· all sports"}`, "ok");
}

